"""mangui guides, batch 10 (GUI tools, standalone pages): burpsuite, ghidra, cyberchef, bloodhound.
For a GUI tool the 'options' are menus, tabs, windows and key presses instead of flags. Examples teach; nothing is captured.
Use these tools only on systems and data you own or are explicitly authorised to test (CTF targets, your lab)."""

GUIDES = []

# ============================================================== burpsuite
GUIDES.append(dict(
    name="burpsuite", section="1", one_line="web security testing proxy (Burp Suite)",
    plain=["Burp Suite sits between your browser and a website. Every request your browser sends goes through Burp first, so you can read it, stop it, change it and send it again. That is how you test what a web app really does, not just what the page lets you click.",
           "The free Community edition has everything a CTF needs: Proxy (catch and change requests), Repeater (resend one request again and again with edits), Decoder (convert encodings), Comparer (diff two responses) and a slow Intruder (automated guessing). Scanner and Collaborator belong to Burp Pro.",
           "The browser must trust Burp's certificate for HTTPS, and be pointed at Burp's listener, normally 127.0.0.1 port 8080. The built-in browser (Proxy > Intercept > Open browser) is already set up for both."],
    when=["See exactly what a web form sends and what the server answers.", "Change a hidden field, cookie, header or parameter and resend.", "Brute-force or fuzz a field with a wordlist.", "Decode a strange token (Base64, URL, hex).", "Save a request for sqlmap (-r)."],
    examples=[("Start the proxy the easy way", "burpsuite  >  Proxy tab  >  Open browser", "The built-in Chromium is pre-configured for the proxy and trusts Burp's CA, so HTTPS works at once. Browse to your lab target in it."),
              ("Catch and edit a request", "Proxy > Intercept > Intercept is on  >  edit the text  >  Forward", "With intercept on, each request waits for you. Change a parameter (price=100 to price=1) in the raw text and press Forward to send it. Turn intercept off to let traffic flow and read it later in HTTP history."),
              ("Resend a request again and again", "Right-click a request in HTTP history > Send to Repeater  (Ctrl+R)\nIn Repeater: edit, then Send  (Ctrl+Space)", "Repeater is your lab bench. Change one thing, press Send, read the response on the right, repeat. This is where most testing happens."),
              ("Guess values with Intruder", "Right-click > Send to Intruder (Ctrl+I) > Positions: select the value, click Add § > Payloads: load a list > Start attack", "Intruder replaces the marked position with every payload. Sort the results by Status or Length: the odd one out is usually the hit. Community Intruder is rate-limited."),
              ("Decode a token", "Decoder tab > paste text > Decode as > Base64 / URL / HTML / Hex", "Quickly turn a cookie or parameter into readable text, or encode your payload before sending."),
              ("Compare two responses", "Right-click a response > Send to Comparer (twice) > Words or Bytes", "Highlights the differences between, for example, a logged-in and a logged-out page."),
              ("Limit Burp to your target", "Target > Site map > right-click the host > Add to scope  (then Proxy > HTTP history > filter: show only in-scope)", "Scope keeps the history readable and prevents you from testing things that are not yours."),
              ("Save a request for sqlmap", "Right-click a request > Copy to file  >  sqlmap -r request.txt", "Saves the raw request with cookies and body so sqlmap can reuse it."),
              ("Replace a response before the browser sees it", "Proxy > Proxy settings > Match and replace", "Rules that rewrite headers or bodies automatically, such as changing 'isAdmin=false' to 'isAdmin=true' in responses.")],
    options=[
        ("Dashboard", "Overview of tasks, issues and events.", "Seeing what Burp is doing."),
        ("Target > Site map", "Tree of hosts and pages Burp has seen. Add to scope from here.", "Mapping the app and setting scope."),
        ("Target > Scope", "The list of addresses you are allowed or want to test.", "Filtering the noise."),
        ("Proxy > Intercept", "Hold each request or response so you can edit it before forwarding.", "Changing live traffic."),
        ("Proxy > HTTP history", "Log of every request and response that passed through.", "Reviewing and picking requests to resend."),
        ("Proxy > WebSockets history", "Log of WebSocket messages.", "Real-time apps."),
        ("Proxy > Proxy settings (Options)", "Listeners (127.0.0.1:8080), intercept rules, match and replace.", "Setup and rewriting."),
        ("Repeater", "Edit and resend one request many times. Ctrl+Space sends. Right pane shows the response; use Pretty, Raw and Render.", "Hands-on testing."),
        ("Intruder", "Send many variants of a request. Attack types: Sniper (one position, one list), Battering ram (one list, all positions at once), Pitchfork (lists in parallel), Cluster bomb (every combination).", "Guessing and fuzzing."),
        ("Decoder", "Encode and decode text: URL, HTML, Base64, ASCII hex, hex, octal, binary, gzip; smart decode; hash.", "Reading tokens."),
        ("Comparer", "Diff two items by words or bytes.", "Spotting differences."),
        ("Sequencer", "Tests how random session tokens are.", "Weak token checks."),
        ("Extensions (BApp Store)", "Add features: Logger++, JWT Editor, Autorize, Hackvertor, Param Miner.", "Specialist tests."),
        ("Collaborator (Pro)", "External server that detects out-of-band callbacks.", "Blind injection and SSRF; Pro only."),
        ("Scanner (Pro)", "Automatic vulnerability scanner.", "Pro only."),
        ("Search / right-click menu", "Send to Repeater, Intruder, Comparer, Decoder; copy as curl; copy to file; engagement tools.", "Moving a request around."),
        ("Ctrl+R / Ctrl+I", "Shortcut: send selected request to Repeater / Intruder.", "Speed."),
        ("Ctrl+Space", "Shortcut in Repeater: send.", "Speed."),
        ("Ctrl+Shift+R / Ctrl+Shift+I", "Switch to the Repeater / Intruder tab.", "Navigation."),
        ("Inspector panel", "Side panel in Repeater and Proxy showing a parsed view of parameters, cookies and headers.", "Editing without breaking the format."),
        ("Burp CA certificate", "Get it from http://burpsuite (browser set to the proxy) and import it into your browser's trusted authorities.", "HTTPS interception in your own browser."),
        ("Project and settings files", "Save the project to keep history; Community only offers temporary projects.", "Preserving work.")],
    mistakes=["Leaving intercept on and thinking the browser is broken: pages hang because Burp is waiting for Forward.", "Testing out-of-scope hosts: set scope and filter the history.", "Forgetting to import the CA certificate in an outside browser: you get certificate warnings.", "Pointing Intruder at a real production site: Intruder is noisy.", "Editing the request and breaking Content-Length: Burp usually fixes it for you, but check when a request fails.", "Using Burp where the event bans proxy tools: read the rules."],
    try_=["Open the built-in browser, log into a lab app and find the login request in HTTP history.", "Send it to Repeater, change the password field and compare responses.", "Send a request to Intruder with a short wordlist and sort by length.", "Copy a request to a file and feed it to sqlmap -r."],
    see_also="curl(1), sqlmap(1), ffuf(1), gobuster(1), tshark(1), wireshark(1), and portswigger.net/web-security for free labs."))

# ============================================================== ghidra
GUIDES.append(dict(
    name="ghidra", section="1", one_line="software reverse-engineering suite (disassembler and decompiler)",
    plain=["Ghidra takes a compiled program (which you cannot read) and turns it back into something you can: assembly instructions, and a rough reconstruction of the original C code called the decompilation. You then read what the program does without having its source.",
           "In CTFs it is the main tool for 'reverse engineering' challenges: find the check that compares your input with the flag, or find the vulnerable function in a pwn binary.",
           "You work inside a project: create a project, import the binary, double-click it to open the CodeBrowser, say yes to analysis, and then explore. Ghidra starts with `ghidraRun`."],
    when=["Find the function that validates a password or a flag.", "Read strings and see where each is used.", "Understand a binary's control flow before exploiting it.", "Rename functions and variables as you learn what they do.", "Compare what the decompiler says with the assembly."],
    examples=[("Open a binary", "ghidraRun  >  File > New Project (Non-Shared) > File > Import File > double-click the file > Yes to analyze > OK", "Import detects the format (ELF, PE) and architecture. The default analysis options are fine for a first pass. Wait for the progress bar at the bottom right."),
              ("Find main", "Symbol Tree (left) > Functions > main   or   Navigation > Go To... (G) > type main", "On stripped binaries main is not named: look for entry, then the function it passes to __libc_start_main."),
              ("Read the decompiler", "Select a function. The right pane (Decompile) shows C-like code. Click a variable to highlight all uses.", "It is a good guess, not the truth. Variable names are invented (local_28, param_1) and types may be wrong."),
              ("Rename something", "Click a name, press L, type a new name, Enter", "Renaming local_28 to input_buf makes the rest of the function read like English. Do it as you learn."),
              ("Fix a variable's type", "Click a variable in the decompiler, press Ctrl+L, enter e.g. char[32]", "A correct type often untangles an array access that looked like a mess."),
              ("Search for interesting strings", "Window > Defined Strings   (or Search > For Strings...)", "Look for 'flag', 'correct', 'wrong', 'password'. Double-click one, then press Ctrl+Shift+F (Show references to) to jump to the code that uses it."),
              ("Follow who calls a function", "Click the function name, then Ctrl+Shift+F or Window > Function Call Trees", "References show every place the function is used: where the check is called."),
              ("See the program as boxes", "Window > Function Graph", "Draws basic blocks with arrows for true/false jumps: ideal for if/else checks."),
              ("Add a comment", "Click a line, press ;  (semicolon), type, Enter", "Notes stay with the project. Use them to record what each step does."),
              ("Run without the GUI", "analyzeHeadless /tmp/proj myproj -import ./crackme -postScript MyScript.py", "The headless mode analyses and scripts binaries in bulk.")],
    options=[
        ("Project window", "Where you create projects and import files. Double-click a file to open the CodeBrowser.", "Starting."),
        ("File > Import File", "Load a binary; choose format and language (architecture).", "Opening a target."),
        ("CodeBrowser: Listing window", "The disassembly: addresses, bytes, instructions, labels.", "Reading assembly."),
        ("CodeBrowser: Decompile window", "C-like reconstruction of the current function.", "Reading logic fast."),
        ("Symbol Tree", "Functions, labels, imports, exports, classes.", "Finding names."),
        ("Program Trees", "Sections of the binary (.text, .data, .rodata).", "Layout."),
        ("Data Type Manager", "Structs, enums and types you can apply.", "Cleaning types."),
        ("Window > Defined Strings", "List of strings found in the binary.", "Hunting for clues."),
        ("Window > Function Graph", "Control-flow graph of a function.", "Understanding branches."),
        ("Window > Bytes / Console / Script Manager", "Raw bytes, log output, built-in scripts.", "Verification and scripts."),
        ("Navigation > Go To (G)", "Jump to an address, label or function.", "Moving around."),
        ("Search > For Strings / Memory (S) / Program Text", "Search strings, bytes or text.", "Finding values."),
        ("L", "Rename the label or variable under the cursor.", "Naming."),
        ("; (semicolon)", "Add an end-of-line comment.", "Notes."),
        ("Ctrl+L", "Retype a variable in the decompiler.", "Fixing types."),
        ("T", "Set the data type at the cursor in the listing.", "Defining data."),
        ("D / C / P", "Disassemble / clear code and data / create function (shortcuts vary by version).", "Fixing bad analysis."),
        ("Ctrl+Shift+F", "Show references to the selected item.", "Who uses this?"),
        ("Edit > Tool Options", "Display, decompiler and analysis settings.", "Customising."),
        ("Analysis > Auto Analyze / One Shot", "Run or re-run analysers.", "After changing the binary or settings."),
        ("Scripts (Java/Python)", "Automate with the Script Manager; PyGhidra for Python 3.", "Bulk tasks."),
        ("ghidraRun / ghidraRun.bat", "Start the GUI.", "Launch."),
        ("analyzeHeadless", "Import and analyse from the command line.", "Batch work."),
        ("Debugger (Ghidra 10.3+)", "Live debugging that uses GDB, LLDB or other back ends.", "Dynamic analysis.")],
    mistakes=["Trusting the decompiler blindly: compare with the assembly when something looks off.", "Not waiting for auto-analysis to finish before reading.", "Choosing the wrong architecture when importing: the code looks like garbage.", "Not renaming as you go: you will re-read the same function many times.", "Skipping dynamic checks: run the binary with gdb or ltrace to confirm what you think it does."],
    try_=["Import a small crackme and find main.", "Rename three variables and one function until the check makes sense.", "Find the string 'wrong' and trace back to the comparison.", "Open the function graph and identify the true/false branch for the right answer."],
    see_also="gdb(1), objdump(1), readelf(1), strings(1), ltrace(1), strace(1), radare2(1), file(1), and ghidra-sre.org."))

# ============================================================== cyberchef
GUIDES.append(dict(
    name="cyberchef", section="1", one_line="the 'Cyber Swiss Army Knife' for encoding, decoding and data analysis",
    plain=["CyberChef is a web page (it also works offline from one HTML file) that converts and analyses data by chaining small operations. You drag operations into a recipe (From Base64, then Gunzip, then XOR...) and the output updates as you build.",
           "It is the fastest way to decode a mystery string in a CTF: Base64, hex, URL encoding, ROT13, XOR, hashing, compression, regular expressions, file type detection, and many more.",
           "The page has four areas: Operations (left, searchable), Recipe (the chain), Input and Output. Because it runs entirely in the browser, your data does not leave your machine when you use the offline copy."],
    when=["Decode an unknown string.", "Chain several decodings (Base64 then hex then gzip).", "Try XOR with a key or brute-force a single-byte key.", "Extract IPs, URLs, emails or flags with a regex.", "Hash or encrypt a value, or find the file type of a blob."],
    examples=[("Decode Base64", "Search 'From Base64', drag it into the Recipe, paste the text in Input", "The decoded text appears in Output. If it is still garbled, add another operation after it."),
              ("Let Magic guess", "Drag 'Magic' into the Recipe", "Magic tries many decoders and shows the ones that produce readable text. Raise the depth to try chains. A superb first move on an unknown blob."),
              ("Chain operations", "From Base64 > From Hex > Gunzip", "Operations run top to bottom. Use the disable and breakpoint icons to debug a chain."),
              ("XOR with a key", "XOR with Key 'k' (UTF8)    or    XOR Brute Force", "XOR Brute Force tries every single-byte key and lets you grep the results for known text (crib) such as 'flag'."),
              ("Extract with a regex", "Regular expression > Output format: List matches   (pattern: flag\\{.*?\\})", "Pulls every match out of a large input. Use 'Extract IP addresses' or 'Extract URLs' for common cases."),
              ("Identify a file", "Detect File Type    or    Extract Files", "Finds magic bytes and can carve out embedded files; the output can be downloaded."),
              ("Hash a value", "MD5 / SHA2 / HMAC / Bcrypt", "Quick checks of a hash against what you have."),
              ("Save and share a recipe", "Save recipe icon > Chef format / Deep link", "A deep link contains your recipe in the URL after #, so you can bookmark or share a decode chain without the data."),
              ("Work from a file", "Open file as input icon (top of Input)", "Loads a binary directly; Output has Save to file.")],
    options=[
        ("Operations list", "Searchable list of hundreds of operations by category (Encryption, Hashing, Data format, Utils, Extractors, Compression...).", "Finding an operation."),
        ("Recipe", "The ordered chain of operations. Drag to reorder; each shows its own arguments.", "Building decodes."),
        ("Input", "Where you paste or load data. Shows length and lines; a drop-down chooses the character encoding.", "Starting data."),
        ("Output", "Result of the recipe; copy, save, or send it back to Input (replace input with output).", "Chaining runs."),
        ("BAKE!", "Run the recipe. Turn on Auto Bake to run after every change.", "Running."),
        ("Step", "Run one operation at a time.", "Debugging a chain."),
        ("Breakpoint / Disable", "Stop before an operation or skip it.", "Debugging."),
        ("Magic", "Auto-detects encodings and file types and suggests a recipe.", "Unknown input."),
        ("From Base64 / To Base64 / From Hex / To Hex / URL Decode / From Binary / From Decimal / From Charcode", "Common encodings in both directions.", "Everyday decoding."),
        ("ROT13 / ROT47 / Caesar-like operations / Vigenere Decode / Atbash", "Classic ciphers.", "Crypto warmups."),
        ("XOR / XOR Brute Force / Bit shift / Rotate", "Bitwise operations.", "Simple obfuscation."),
        ("AES / DES / RC4 / Blowfish Decrypt", "Standard ciphers with key and IV fields.", "Known-key decryption."),
        ("Gunzip / Gzip / Bzip2 Decompress / Unzip / Raw Inflate / Zlib Inflate", "Compression operations.", "Packed data."),
        ("MD5 / SHA1 / SHA2 / HMAC / Bcrypt / Hash", "Hash generation.", "Checking hashes."),
        ("Regular expression / Find / Replace / Extract IP addresses / Extract URLs", "Search, replace and extract.", "Finding values."),
        ("Detect File Type / Extract Files / Entropy / Strings / Parse X.509 certificate", "Analysis of binaries.", "Forensics."),
        ("To Hexdump / From Hexdump / Hex Dump", "xxd-style views.", "Reading bytes."),
        ("Fork / Merge / Register / Subsection", "Flow control: run operations on each line or on a part.", "Complex recipes."),
        ("Save / Load recipe", "Store a recipe as JSON or a link.", "Reusing and sharing."),
        ("Offline use", "Download the release zip and open CyberChef_*.html in a browser.", "No internet or private data.")],
    mistakes=["Pasting binary data into the Input and having it altered by character encoding: use 'Open file as input' for binaries.", "Wrong order of operations: always decode in the reverse of how it was encoded.", "Trusting Magic blindly: check the output makes sense.", "Using the online site for secrets: use the offline copy.", "Forgetting that Output replaced Input: use the 'replace input' button deliberately."],
    try_=["Decode 'SGVsbG8gQ3liZXJTY2k=' with From Base64.", "Use Magic on a string you do not recognise.", "Build From Base64 > From Hex > Gunzip for a nested test string you make yourself.", "Run XOR Brute Force and search for 'flag'."],
    see_also="base64(1), xxd(1), openssl(1), tr(1), gzip(1), strings(1), file(1), exiftool(1), binwalk(1), and gchq.github.io/CyberChef."))

# ============================================================== bloodhound
GUIDES.append(dict(
    name="bloodhound", section="1", one_line="map Active Directory attack paths as a graph",
    plain=["An Active Directory (AD) domain is a big web of users, groups, computers and permissions. BloodHound collects that data, draws it as a graph and answers: starting from this user, what is the shortest path to Domain Admin?",
           "You use it in two steps. First a collector gathers data from the domain (SharpHound on Windows, bloodhound-python from Linux). Second you upload the zip into BloodHound and run queries or click through the graph.",
           "It is used by defenders to find and cut dangerous paths, and by pen testers and CTF players in authorised labs. Use it only on domains you own or have permission to test."],
    when=["Find who has admin on which machines.", "Find the shortest path from a compromised user to Domain Admins.", "List Kerberoastable and AS-REP-roastable accounts.", "Find dangerous permissions (GenericAll, WriteDacl, DCSync rights).", "As a defender, measure and reduce attack paths."],
    examples=[("Collect from Linux (lab)", "bloodhound-python -u alice -p 'Passw0rd!' -d corp.local -ns 10.10.10.2 -c All --zip", "-u/-p are lab credentials, -d the domain, -ns the DNS server (usually the domain controller), -c All collects everything, --zip packs the JSON files for upload."),
              ("Collect from Windows (lab)", ".\\SharpHound.exe -c All --zipfilename corp.zip", "SharpHound runs on a domain-joined host and writes a zip. Some environments detect and block it."),
              ("Start and sign in", "sudo bloodhound-setup; bloodhound", "On Kali the legacy version needs Neo4j started and its password set once. Newer BloodHound Community Edition runs as a web service; follow its first-run instructions."),
              ("Upload the data", "Upload Data (right side) > select the zip", "The graph fills as the files are imported. Wait for the import to finish before querying."),
              ("Run a pre-built query", "Analysis > Shortest Paths to Domain Admins", "Draws the shortest chains of relationships from any account to the Domain Admins group. Click each edge for help on how to abuse or fix it."),
              ("Mark what you own", "Right-click a user > Mark User as Owned", "Owned accounts are the starting points. Then use 'Shortest Paths from Owned Principals'."),
              ("Find Kerberoastable accounts", "Analysis > List all Kerberoastable Accounts", "Service accounts with a service principal name can have their tickets requested and cracked offline."),
              ("Find AS-REP roastable accounts", "Analysis > Find AS-REP Roastable Users", "Accounts that do not require Kerberos pre-authentication leak crackable data."),
              ("Look up one account", "Search box > type the name > click it", "Shows its properties, group memberships, sessions and outbound control in the node panel."),
              ("Write your own query", "Raw Query bar: MATCH p=shortestPath((u:User {name:'ALICE@CORP.LOCAL'})-[*1..]->(g:Group {name:'DOMAIN ADMINS@CORP.LOCAL'})) RETURN p", "The Cypher language lets you ask any question of the graph. This one is the shortest path from one user to Domain Admins.")],
    options=[
        ("Search bar", "Find a node by name.", "Starting a path."),
        ("Pathfinding", "Pick a start and an end node; BloodHound draws a path.", "Direct questions."),
        ("Analysis (Queries) tab", "Pre-built queries: Domain Admins, Shortest Paths to Domain Admins, Kerberoastable, AS-REP roastable, unconstrained delegation, high-value targets.", "Quick wins."),
        ("Node Info", "Properties, memberships, sessions, local admin rights for the selected node.", "Details."),
        ("Mark as Owned / Mark as High Value", "Flag nodes you control or want to reach.", "Planning paths."),
        ("Raw Query (Cypher)", "Run your own graph queries.", "Custom questions."),
        ("Upload Data", "Import collector zip or JSON files.", "Loading data."),
        ("Clear Database", "Delete all graph data.", "Starting fresh."),
        ("Edges: MemberOf", "A user or group is a member of a group; privileges flow upwards.", "Reading paths."),
        ("Edges: AdminTo", "The principal is a local admin on a computer.", "Lateral movement."),
        ("Edges: HasSession", "A user has a logged-on session on a computer; credentials may be in memory.", "Credential exposure."),
        ("Edges: CanRDP / CanPSRemote", "Remote login rights.", "Access paths."),
        ("Edges: GenericAll / GenericWrite / WriteOwner / WriteDacl", "Powerful rights over an object.", "Taking over an object."),
        ("Edges: ForceChangePassword / AddMember", "Reset a password or add yourself to a group.", "Privilege escalation."),
        ("Edges: AllExtendedRights / DCSync (GetChanges + GetChangesAll)", "Rights that include reading password data.", "Domain compromise."),
        ("Collector: SharpHound -c All|DCOnly|Session|LoggedOn|Group|ACL|Trusts", "Collection methods.", "Choosing how loud to be."),
        ("Collector: bloodhound-python -u -p -d -ns -c --zip", "Python collector for Linux.", "Remote collection with credentials."),
        ("Collector: --dns-tcp, --disable-pooling, -w N", "Network and performance options.", "Slow or unusual labs."),
        ("Edge help (right-click an edge > Help)", "Explains how the relationship can be abused and how to fix it.", "Learning and remediation.")],
    mistakes=["Treating BloodHound as proof of vulnerability: it shows possible paths; confirm each step.", "Collecting with -c All on a monitored network: it is noisy.", "Forgetting DNS: bloodhound-python often needs -ns pointing to the domain controller.", "Importing partial or old data and trusting an old graph.", "Using it on a domain you do not own: it generates real queries and logs."],
    try_=["Collect data from a lab domain and import it.", "Run 'Shortest Paths to Domain Admins' and read the edge help for each step.", "Mark one user as owned and find paths from it.", "List Kerberoastable accounts and write what a defender could change."],
    see_also="nmap(1), smbclient(1), enum4linux(1), crackmapexec(1), impacket scripts, ldapsearch(1), and the BloodHound docs at support.bloodhoundenterprise.io."))
